def search_land_zones() -> str:
    """
    21개 용도지역의 건폐율/용적률 규제 목록을 조회합니다.
    GET http://127.0.0.1:8000/land/zones/

    Returns:
        JSON string with all zoning zones and their BCR/FAR limits
    """
    import requests, json
    try:
        resp = requests.get("http://127.0.0.1:8000/land/zones/", timeout=30)
        resp.raise_for_status()
        return json.dumps(resp.json(), ensure_ascii=False, indent=2)
    except requests.exceptions.ConnectionError:
        return json.dumps({"error": "ARR Django 서버 미실행 (http://127.0.0.1:8000). python manage.py runserver 8000 으로 시작하세요."}, ensure_ascii=False)
    except Exception as e:
        return json.dumps({"error": str(e)}, ensure_ascii=False)

def analyze_land_regulation(pnu_or_address: str, input_type: str = "pnu", zones_json: str = "[]", include_law: bool = True) -> str:
    """
    토지 규제 분석: 건폐율(BCR), 용적률(FAR), 건축제한, 관련 법조항.
    POST http://127.0.0.1:8000/land/analyze/

    Args:
        pnu_or_address: PNU 코드(19자리) 또는 주소 또는 빈 문자열(raw 모드시)
        input_type: "pnu" | "address" | "raw" (raw는 zones만 사용)
        zones_json: JSON 배열 문자열, 예: '["제1종일반주거지역"]'
        include_law: 관련 법조항 검색 여부 (기본 True)

    Returns:
        JSON string with regulation, law_articles, restrictions
    """
    import requests, json
    try:
        zones = json.loads(zones_json) if zones_json else []
    except json.JSONDecodeError:
        zones = []
    payload = {
        "input": pnu_or_address,
        "input_type": input_type,
        "zones": zones,
        "include_law": include_law
    }
    try:
        resp = requests.post("http://127.0.0.1:8000/land/analyze/", json=payload, timeout=30)
        resp.raise_for_status()
        return json.dumps(resp.json(), ensure_ascii=False, indent=2)
    except requests.exceptions.ConnectionError:
        return json.dumps({"error": "ARR Django 서버 미실행 (http://127.0.0.1:8000). python manage.py runserver 8000 으로 시작하세요."}, ensure_ascii=False)
    except Exception as e:
        return json.dumps({"error": str(e)}, ensure_ascii=False)

def resolve_land_pnu(input_val: str, input_type: str = "pnu") -> str:
    """
    주소→PNU 변환 또는 PNU 검증/파싱.
    POST http://127.0.0.1:8000/land/resolve/

    Args:
        input_val: PNU 코드(19자리) 또는 주소
        input_type: "pnu" (검증/파싱) 또는 "address" (Vworld 지오코딩)

    Returns:
        JSON string with parsed PNU info or geocoding result
    """
    import requests, json
    payload = {
        "input": input_val,
        "input_type": input_type
    }
    try:
        resp = requests.post("http://127.0.0.1:8000/land/resolve/", json=payload, timeout=30)
        resp.raise_for_status()
        return json.dumps(resp.json(), ensure_ascii=False, indent=2)
    except requests.exceptions.ConnectionError:
        return json.dumps({"error": "ARR Django 서버 미실행 (http://127.0.0.1:8000). python manage.py runserver 8000 으로 시작하세요."}, ensure_ascii=False)
    except Exception as e:
        return json.dumps({"error": str(e)}, ensure_ascii=False)

def search_law_articles(query: str, limit: int = 10) -> str:
    """
    Neo4j 법률 DB에서 관련 법조항을 하이브리드 검색합니다.
    POST http://127.0.0.1:8011/api/search

    Args:
        query: 검색어 (예: "제1종일반주거지역 건폐율", "제76조")
        limit: 최대 결과 수 (기본 10)

    Returns:
        JSON string with search results including hang_id, content, similarity, law_name
    """
    import requests, json
    payload = {
        "query": query,
        "limit": limit
    }
    try:
        resp = requests.post("http://127.0.0.1:8011/api/search", json=payload, timeout=30)
        resp.raise_for_status()
        return json.dumps(resp.json(), ensure_ascii=False, indent=2)
    except requests.exceptions.ConnectionError:
        return json.dumps({"error": "법률 검색 서버 미실행 (http://127.0.0.1:8011). law-domain-agents 서버를 시작하세요."}, ensure_ascii=False)
    except Exception as e:
        return json.dumps({"error": str(e)}, ensure_ascii=False)
